INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1803', 'vocabulary', 'aufregen', 'agitate / upset emotionally', 'to upset / to excite / to agitate', '{"de":"Es regt mich auf, dass ich schon wieder Überstunden machen muss. / Ganz ruhig! Bitte regen Sie sich nicht auf. / Heute hast du eine Prüfung. Bist du schon aufgeregt?","en":"It upsets me that I have to do overtime again. / Calm down! Please do not get agitated. / You have an exam today. Are you excited already?"}', '["B1"]', 'verb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"very_common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["emotions","stress"]', '[]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":true,"isSeparable":true,"auxiliary":"haben","forms":{"presentErSieEs":"regt auf","praeteritum":"regte auf","partizipII":"aufgeregt"},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["acc, refl, über + acc"]', '{"synonyms":["sich über Kleinigkeiten aufregen"],"antonyms":["empören","ärgern","beunruhigen"],"falseFriends":["beruhigen"],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":88,"url":"https://www.goethe.de"}', 'draft');
