INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1960', 'vocabulary', 'dafür', 'in favor of / in return for that', 'for it / in favor of it', '{"de":"Meine Schwester interessiert sich für Politik. Ich interessiere mich nicht dafür. / Ich bin dafür, dass wir möglichst früh losfahren.","en":"My sister is interested in politics. I am not interested in that. / I am in favor of us setting off as early as possible."}', '["B1"]', 'adverb', '{"nativeFrequencyRating":5,"nativeFrequencyLabel":"essential","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["opinion","prepositional adverb"]', '["adverb"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["dafür sein"]', '{"synonyms":["zugunsten","dafür"],"antonyms":["dagegen"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":245,"url":"https://www.goethe.de"}', 'draft');
INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1961', 'vocabulary', 'dagegen', 'in collision with / opposed to', 'against it / in contrast / opposed', '{"de":"Vorsicht, da ist ein Baum! Fahr nicht dagegen! / Sind Sie für oder gegen ein Rauchverbot? - Ich bin dagegen. / Ich habe nichts dagegen, dass wir schon nach Hause gehen.","en":"Watch out; there is a tree! Don''t drive into it! / Are you in favor of or against a smoking ban? - I am against it. / I have nothing against us going home already."}', '["B1"]', 'adverb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"very_common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["opinion","prepositional adverb"]', '["adverb"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["dagegen sein","nichts dagegen haben"]', '{"synonyms":["wider","konträr"],"antonyms":["dafür"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":246,"url":"https://www.goethe.de"}', 'draft');
