INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1963', 'vocabulary', 'dahin', 'to that place or up to that point in time', 'there / until then', '{"de":"Der Zug kommt in 30 Minuten. Bis dahin können wir einen Kaffee trinken.","en":"The train arrives in 30 minutes. Until then we can drink a coffee."}', '["B1"]', 'adverb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"very_common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["temporal","spatial"]', '["adverb"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["bis dahin"]', '{"synonyms":["dorthin","bis zu dem Zeitpunkt"],"antonyms":["von dort"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":248,"url":"https://www.goethe.de"}', 'draft');
