INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1970', 'vocabulary', 'Dauer', 'length of continuous time', 'duration / period', '{"de":"Sie können das Buch für die Dauer einer Woche ausleihen. / Auf Dauer ist die Arbeit nicht interessant.","en":"You can borrow the book for a period of one week. / In the long run the work is not interesting."}', '["B1"]', 'noun', '{"nativeFrequencyRating":3,"nativeFrequencyLabel":"common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '[]', '["time"]', '{"gender":"die","plural":"-","genitiveSingular":"Dauer","isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["auf Dauer","für die Dauer von"]', '{"synonyms":["Zeitspanne","Frist","Verlauf"],"antonyms":["Ende"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":255,"url":"https://www.goethe.de"}', 'draft');
