INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-1995', 'vocabulary', 'doch', 'affirmative reply to negative question / modal particle', 'yes (after negative) / but / after all / surely', '{"de":"Isst du kein Fleisch? - Doch, manchmal schon. / Ich habe es mir anders überlegt. Ich komme doch mit in die Stadt. / Ihr kommt doch heute Abend? / Fragen Sie doch Herrn Müller, der ist Computerspezialist. / Ach, wenn doch schon Sonntag wäre!","en":"Don''t you eat meat? - Yes; sometimes. / I changed my mind. I am coming along into town after all. / You are coming tonight; aren''t you? / Why don''t you ask Mr. Müller; he is a computer specialist. / Ah; if only it were Sunday already!"}', '["B1"]', 'adverb', '{"nativeFrequencyRating":5,"nativeFrequencyLabel":"essential","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["discourse","emphasis","particle"]', '["particle"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["nicht wahr","ja wohl"]', '{"synonyms":["allerdings","gewiss"],"antonyms":["nein"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":280,"url":"https://www.goethe.de"}', 'draft');
