INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-2004', 'vocabulary', 'drehen', 'rotate on an axis / turn object or head', 'to turn / to rotate / to revolve', '{"de":"Drehen Sie zum Einschalten den Schalter nach rechts. / Die Kinder drehen sich zur Musik im Kreis. / Bei Familie Huber dreht sich jetzt alles um das Baby.","en":"To switch it on turn the switch to the right. / The children turn in circles to the music. / In the Huber family everything now revolves around the baby."}', '["B1"]', 'verb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"very_common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["movement","direction"]', '[]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":true,"isSeparable":false,"auxiliary":"haben","forms":{"presentErSieEs":"dreht","praeteritum":"drehte","partizipII":"gedreht"},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["acc, refl"]', '{"synonyms":["den Kopf drehen","sich im Kreis drehen"],"antonyms":["rotieren","wenden","schwenken"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":289,"url":"https://www.goethe.de"}', 'draft');
INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-2005', 'vocabulary', 'drin', 'inside an interior container or room', 'inside / in there', '{"de":"Wo wollt ihr sitzen? Draußen oder drinnen? / Bei der Hitze ist es drinnen viel angenehmer. / In der Packung ist nichts mehr drin.","en":"Where do you want to sit? Outside or inside? / In this heat it is much more pleasant inside. / There is nothing left in the package."}', '["B1"]', 'adverb', '{"nativeFrequencyRating":4,"nativeFrequencyLabel":"very_common","nativeFrequencyNotes":"Short form of drinnen","ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '["spatial","location"]', '["adverb"]', '{"gender":null,"plural":null,"genitiveSingular":null,"isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["drin sein","da drin"]', '{"synonyms":["drinnen","im Inneren"],"antonyms":["draußen"],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":290,"url":"https://www.goethe.de"}', 'draft');
