INSERT OR REPLACE INTO content_items (id, type, term, sense, translation, examples_json, levels_json, part_of_speech, usage_json, contexts_json, tags_json, grammar_json, collocations_json, related_json, source_json, review_status) VALUES ('w-2010', 'vocabulary', 'Durchschnitt', 'arithmetical mean or typical average', 'average / mean', '{"de":"Der Durchschnitt der Ausgaben liegt bei 150 Euro im Monat. / Im Durchschnitt brauchen wir täglich 20 Minuten zur Arbeit. / Die Studentin gehört zum Durchschnitt.","en":"The average of the expenses is 150 euros per month. / On average we need 20 minutes to get to work daily. / The female student belongs to the average."}', '["B1"]', 'noun', '{"nativeFrequencyRating":3,"nativeFrequencyLabel":"common","nativeFrequencyNotes":null,"ratedBy":null,"ratedAt":null,"corpusRank":null,"editorialFrequencyHint":null,"register":"neutral","regionalLabels":[]}', '[]', '["math","statistics"]', '{"gender":"der","plural":"-e","genitiveSingular":"Durchschnitts","isReflexive":false,"isSeparable":false,"auxiliary":null,"forms":{"presentErSieEs":null,"praeteritum":null,"partizipII":null},"valency":[],"connectorFunction":null,"verbPositionEffect":null,"highlightedExample":null,"nounArticleRule":null}', '["im Durchschnitt","über/unter dem Durchschnitt"]', '{"synonyms":["Mittelwert","Normalmaß"],"antonyms":[],"falseFriends":[],"wordFamily":[]}', '{"kind":"manual_entry","name":"Goethe-Zertifikat B1 Wortliste","file":"data/b1-all.csv","row":295,"url":"https://www.goethe.de"}', 'draft');
